mapper.select:
/*selectBuyerMpStWarehouseGiList*/ SELECT CAR.IV_NO AS IV_NO ,CAR.ADD_DATE AS IV_DATE ,CAR.BUYER_ITEM_NO AS BUYER_ITEM_NO ,BYIT.DESCRIPTION_LOC AS DESCRIPTION ,BYIT.SPECIFICATION AS SPECIFICATION ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE = BYIT.MAKER_CODE) AS MAKER_NAME ,BYIT.UNIT_MEASURE AS UNIT_MEASURE ,CAR.IV_QTY AS IV_QTY ,CAR.CAR_NO AS CAR_NO ,CAR.ADD_USER_ID AS ADD_USER_ID ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = CAR.ADD_USER_ID) AS ADD_USER_NAME ,BYIT.BUYER AS BYIT_COMORG_CODE ,(SELECT CONTRACT_NO FROM ICOMCQDT WHERE BUYER=BYIT.BUYER AND BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND ROWNUM=1) AS CONTRACT_NO ,(SELECT CONTRACT_SEQ FROM ICOMCQDT WHERE BUYER=BYIT.BUYER AND BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND ROWNUM=1) AS CONTRACT_SEQ
FROM CAR_STOCK_IVDT CAR , ICOMBYIT BYIT WHERE CAR.BUYER = #{st_buyer} AND BYIT.BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = CAR.BUYER) AND BYIT.BUYER_ITEM_NO = CAR.BUYER_ITEM_NO AND BYIT.PRODUCT_CLOSE_FLAG = 'N' AND BYIT.STATUS != 'D' AND CAR.STATUS != 'D'
AND BYIT.DESCRIPTION_LOC LIKE '%' || #{st_description} || '%'
AND BYIT.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND CAR.CAR_NO LIKE '%' || #{st_car_no} || '%'
AND CAR.ADD_USER_ID = #{st_add_user_id}
AND TO_CHAR(CAR.ADD_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}

mapper.update:

/*updateBuyerMpStWarehouseGiMinus*/
	UPDATE CAR_STOCK
	SET IV_QTY = IV_QTY - #{IV_QTY}
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}

	WHERE BUYER = #{st_buyer}
	AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
	AND STATUS != 'D'


/*deleteBuyerMpStWarehouseGi*/
	UPDATE CAR_STOCK_IVDT
	SET STATUS = 'D'
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}

	WHERE BUYER = #{st_buyer}
	AND IV_NO = #{IV_NO}
	AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
	AND STATUS != 'D'

mapper.select:

/*selectBuyerMpStWarehouseGiStockCheck*/
SELECT COUNT(1) AS CNT
FROM CAR_STOCK CAR
WHERE CAR.BUYER = #{st_buyer}
AND CAR.BUYER_ITEM_NO = #{BUYER_ITEM_NO}


/*selectBuyerMpStWarehouseGiCheckQty*/
SELECT
	(IV_QTY-#{IV_QTY}) AS CHECK_QTY
FROM CAR_STOCK
WHERE BUYER = #{st_buyer}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}


/*selectBuyerMpStWarehouseGiCheckStockQty*/
SELECT
	(GR_QTY-IV_QTY)-#{IV_QTY} AS CHECK_QTY
FROM CAR_STOCK
WHERE BUYER = #{st_buyer}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}

mapper.update:

/*updateBuyerMpStWarehouseGiAdd*/
	UPDATE CAR_STOCK
	SET IV_QTY = IV_QTY + #{IV_QTY}
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}

	WHERE BUYER = #{st_buyer}
	AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
	AND STATUS != 'D'
